function sendMessage()
{
    const input = document.getElementById('chatInput');
    const message = input.value;

    if (message)
    {
        // Enviar mensagem para o servidor
        fetch('send_message.php',
            {
                method: 'POST',
                headers: 'Content-Type: application/x-www-form-urlencoded',
                body: 'message=' + encodeURIComponent(message) + '&user_id=' + <?php echo $_SESSION['user_id']; ?>
            })
            .then(response => response.text())
            .then(data =>
                document.getElementById('chatMessages').innerHTML += '<div class="message ' + 'sent">';
                document.getElementById('chatMessages').innerHTML += htmlDecode(data);
                document.getElementById('chatInput').value = '';
                document.getElementById('chatInput').focus();
            });
    }
}
